package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class LargeTwoStepStoriesTest {
 private void verify(Question q){int[] v=TwoStepChangeStories.read(q);assertNotNull(v);int middle=v[0]+(v[3]==1?v[1]:-v[1]),result=middle+(v[4]==1?v[2]:-v[2]);assertEquals(middle,v[5]);assertEquals(result,v[6]);assertTrue(middle>=0&&middle<=1000000&&result>=0&&result<=1000000);q.answers=new String[]{"poison"};q.expression="poison";assertTrue(new Checker().check(q,List.of(),List.of(""+result)).correct());assertEquals(Checker.Status.WRONG_ANSWER,new Checker().check(q,List.of(),List.of(""+(result+1))).status);HelpPlan h=HelpPlan.forQuestion(q);assertEquals(4,h.size());assertFalse(h.canTransfer());assertTrue(h.step(0).accepts(v[3]==1?"+":"-"));assertFalse(h.step(0).accepts(v[3]==1?"-":"+"));assertTrue(h.step(1).accepts(""+middle));assertTrue(h.step(2).accepts(v[4]==1?"+":"-"));assertTrue(h.step(3).accepts(""+result));for(int i:new int[]{1,3})assertFalse(h.step(i).before.matches(".*[0-9].*"));}
 @Test public void normalGradeFiveSupplyIncludesMixedChangesAndEveryMagnitude(){CurriculumLimits limits=GlobalCurriculum.limits("england-primary-2021-v1",TwoStepChangeStories.ID,5);assertTrue(limits.allows(TwoStepChangeStories.make(0,1000000,150000,false,300000,false)));Generator g=new Generator(new Random(161));List<String> history=new ArrayList<>();Set<String> ops=new HashSet<>();Set<Integer> changes=new HashSet<>();boolean large=false;for(int i=0;i<400;i++){Question q=g.next(TwoStepChangeStories.ID,history,false,limits);assertFalse(history.contains(q.signature()));history.add(q.signature());int[] v=TwoStepChangeStories.read(q);ops.add(v[3]+":"+v[4]);changes.add(v[1]);changes.add(v[2]);large|=v[0]>9999;verify(q);}assertTrue(large);assertEquals(4,ops.size());for(int c:LargeTwoStepSupply.CHANGES)assertTrue(changes.contains(c));assertEquals(9999,GlobalCurriculum.limits("england-primary-2021-v1",TwoStepChangeStories.ID,4).wholeMaximum(9999));}
 @Test public void independentSmallDomainExhaustionAndLargeSegmentEdges(){int max=4;int[] changes={1,2};Set<String> expected=new HashSet<>();for(int context=0;context<2;context++)for(int start=0;start<=max;start++)for(int first:changes)for(int second:changes)for(int op=0;op<4;op++){int middle=start+((op&1)==0?first:-first),result=middle+((op&2)==0?second:-second);if(middle<0||middle>max||result<0||result>max)continue;expected.add(TwoStepChangeStories.make(context,start,first,(op&1)==0,second,(op&2)==0).signature());}long count=LargeTwoStepSupply.count(max,changes);assertEquals(expected.size(),count);Set<String> indexed=new HashSet<>();for(long i=0;i<count;i++){Question q=LargeTwoStepSupply.indexed(max,changes,i);verify(q);assertTrue(indexed.add(q.signature()));}assertEquals(expected,indexed);Map<String,Integer> history=new LinkedHashMap<>();Random random=new Random(161);for(int i=0;i<count;i++){Question q=LongIndexedQuestionSupply.choose(count,n->LargeTwoStepSupply.indexed(max,changes,n),random,new CurriculumLimits(""),history);assertFalse(history.containsKey(q.signature()));history.put(q.signature(),i);}assertEquals(0,(int)history.get(LongIndexedQuestionSupply.choose(count,n->LargeTwoStepSupply.indexed(max,changes,n),random,new CurriculumLimits(""),history).signature()));long large=LargeTwoStepSupply.count(1000000,LargeTwoStepSupply.CHANGES);assertTrue(large>100000000);for(long i:new long[]{0,1,large/2,large-2,large-1})verify(LargeTwoStepSupply.indexed(1000000,LargeTwoStepSupply.CHANGES,i));}
 @Test public void millionZeroAndMalformedPublicConditions(){for(Question q:List.of(TwoStepChangeStories.make(0,1000000,1,false,1,true),TwoStepChangeStories.make(1,0,300000,true,300000,false),TwoStepChangeStories.make(0,1000000,300000,false,300000,false)))verify(q);Question q=TwoStepChangeStories.make(0,1000000,1,false,1,true);for(String raw:List.of(q.prompt.replace("처음: 1000000","처음: 1000001"),q.prompt.replace("1개를 나눠","1000001개를 나눠"),q.prompt.replace("나눠 줬어요","더 받았어요"),"unknown")){Question bad=TwoStepChangeStories.make(0,1000000,1,false,1,true);bad.prompt=raw;assertNull(TwoStepChangeStories.read(bad));assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(bad,List.of(),List.of("1000000")).status);}assertEquals(9999,GlobalCurriculum.limits("kr-national",TwoStepChangeStories.ID,5).wholeMaximum(9999));}
}
